package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashSet;
import java.util.Iterator;
import org.apache.commons.jxpath.Expression;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.apache.commons.jxpath.ri.compiler.CoreOperationCompare;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for CoreOperationCompare.equal method.
 * Note: Since the method is protected, we use a Testable subclass to access it.
 */
public class CoreOperationCompare_equal_TriageGen1Test {

    private TestableCoreOperationCompare compare;

    // Mocking Pointer interface as it is used in the method logic
    interface Pointer {
        Object getValue();
    }

    // Subclass to expose protected method for testing
    private static class TestableCoreOperationCompare extends CoreOperationCompare {
        public TestableCoreOperationCompare(Expression arg1, Expression arg2) {
            super(arg1, arg2);
        }

        @Override
        public boolean equal(Object l, Object r) {
            return super.equal(l, r);
        }
    }

    @Before
    public void setUp() {
        // Expression is required for constructor but not used in equal()
        Expression mockExpr = mock(Expression.class);
        compare = new TestableCoreOperationCompare(mockExpr, mockExpr);
    }

    @Test
    public void testEqual_BothPointersSame() {
        Pointer p1 = mock(Pointer.class);
        Pointer p2 = mock(Pointer.class);
        when(p1.equals(p2)).thenReturn(true);
        assertTrue(compare.equal(p1, p2));
    }

    @Test
    public void testEqual_BothPointersDifferent() {
        Pointer p1 = mock(Pointer.class);
        Pointer p2 = mock(Pointer.class);
        when(p1.equals(p2)).thenReturn(false);
        // After falling through pointer check, it will try to unwrap them
        when(p1.getValue()).thenReturn(10);
        when(p2.getValue()).thenReturn(20);
        assertFalse(compare.equal(p1, p2));
    }

    @Test
    public void testEqual_LeftPointerUnwrap() {
        Pointer p1 = mock(Pointer.class);
        when(p1.getValue()).thenReturn("test");
        assertTrue(compare.equal(p1, "test"));
    }

    @Test
    public void testEqual_RightPointerUnwrap() {
        Pointer p2 = mock(Pointer.class);
        when(p2.getValue()).thenReturn("test");
        assertTrue(compare.equal("test", p2));
    }

    @Test
    public void testEqual_BothPointersUnwrapToSame() {
        Pointer p1 = mock(Pointer.class);
        Pointer p2 = mock(Pointer.class);
        when(p1.getValue()).thenReturn(100);
        when(p2.getValue()).thenReturn(100);
        assertTrue(compare.equal(p1, p2));
    }

    @Test
    public void testEqual_NullIdentity() {
        assertTrue(compare.equal(null, null));
        assertFalse(compare.equal(null, "not null"));
    }

    @Test
    public void testEqual_SameObjectReference() {
        Object obj = new Object();
        assertTrue(compare.equal(obj, obj));
    }

    @Test
    public void testEqual_BooleanLogic() {
        // Testing Boolean branch
        assertTrue(compare.equal(true, true));
        assertFalse(compare.equal(true, false));
        // Testing cross-type boolean (requires InfoSetUtil behavior)
        // Assuming InfoSetUtil handles Boolean/Integer conversion
        assertTrue(compare.equal(true, 1)); 
    }

    @Test
    public void testEqual_NumberLogic() {
        // Testing Number branch
        assertTrue(compare.equal(10, 10.0));
        assertFalse(compare.equal(10, 20));
        // Testing NaN (per comment logic, NaN == NaN is false in double comparison)
        assertTrue(Double.isNaN(compare.equal(Double.NaN, Double.NaN)) == false); 
        // Note: The method returns boolean, so we check if it returns false for NaN
        assertFalse(compare.equal(Double.NaN, Double.NaN));
    }

    @Test
    public void testEqual_StringLogic() {
        // Testing String branch
        assertTrue(compare.equal("hello", "hello"));
        assertFalse(compare.equal("hello", "world"));
        // Testing cross-type String (if InfoSetUtil converts Number to String)
        assertTrue(compare.equal("123", 123));
    }

    @Test
    public void testEqual_GenericObjectEquals() {
        // Testing final l != null && l.equals(r) branch
        Object customObj1 = new CustomObject("val");
        Object customObj2 = new CustomObject("val");
        assertTrue(compare.equal(customObj1, customObj2));

        Object customObj3 = new CustomObject("diff");
        assertFalse(compare.equal(customObj1, customObj3));
    }

    @Test
    public void testEqual_NullPointerUnwrap() {
        // Verify that if pointer unwrap results in null
        Pointer p = mock(Pointer.class);
        when(p.getValue()).thenReturn(null);
        assertTrue(compare.equal(p, null));
    }

    // Helper class for generic equality test
    private static class CustomObject {
        private final String val;
        CustomObject(String val) { this.val = val; }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            CustomObject that = (CustomObject) o;
            return val.equals(that.val);
        }
        @Override
        public int hashCode() { return val.hashCode(); }
    }
}
